description:
Write `#[derive(Debug, Clone, PartialEq)] struct Matrix { rows: usize, cols: usize, data: Vec<f64> }` with:

- `impl TryFrom<Vec<Vec<f64>>> for Matrix` with `type Error = String`: refuses an empty input, an empty first row and rows of different lengths;
- `Index<(usize, usize)>` and `IndexMut<(usize, usize)>` for `m[(row, col)]`, panicking outside the matrix;
- `impl Mul for &Matrix` with `Output = Matrix`, the matrix product (it panics when the inner sizes differ);
- `fn identity(n: usize) -> Matrix` and `fn transpose(&self) -> Matrix`.

starter.solution.rs:
use std::ops::{Index, IndexMut, Mul};

#[derive(Debug, Clone, PartialEq)]
struct Matrix {
    rows: usize,
    cols: usize,
    data: Vec<f64>,
}

solution.solution.rs:
use std::ops::{Index, IndexMut, Mul};

#[derive(Debug, Clone, PartialEq)]
struct Matrix {
    rows: usize,
    cols: usize,
    data: Vec<f64>,
}

impl TryFrom<Vec<Vec<f64>>> for Matrix {
    type Error = String;
    fn try_from(v: Vec<Vec<f64>>) -> Result<Self, Self::Error> {
        let rows = v.len();
        if rows == 0 {
            return Err("no rows".into());
        }
        let cols = v[0].len();
        if cols == 0 {
            return Err("empty row".into());
        }
        if v.iter().any(|r| r.len() != cols) {
            return Err("rows have different lengths".into());
        }
        Ok(Matrix { rows, cols, data: v.into_iter().flatten().collect() })
    }
}

impl Index<(usize, usize)> for Matrix {
    type Output = f64;
    fn index(&self, (r, c): (usize, usize)) -> &f64 {
        assert!(r < self.rows && c < self.cols, "index ({r}, {c}) outside a {}x{} matrix", self.rows, self.cols);
        &self.data[r * self.cols + c]
    }
}

impl IndexMut<(usize, usize)> for Matrix {
    fn index_mut(&mut self, (r, c): (usize, usize)) -> &mut f64 {
        assert!(r < self.rows && c < self.cols, "index ({r}, {c}) outside a {}x{} matrix", self.rows, self.cols);
        &mut self.data[r * self.cols + c]
    }
}

impl Mul for &Matrix {
    type Output = Matrix;
    fn mul(self, o: &Matrix) -> Matrix {
        assert_eq!(self.cols, o.rows, "sizes do not match");
        let mut out = Matrix { rows: self.rows, cols: o.cols, data: vec![0.0; self.rows * o.cols] };
        for r in 0..self.rows {
            for c in 0..o.cols {
                out[(r, c)] = (0..self.cols).map(|k| self[(r, k)] * o[(k, c)]).sum();
            }
        }
        out
    }
}

impl Matrix {
    fn identity(n: usize) -> Matrix {
        let mut m = Matrix { rows: n, cols: n, data: vec![0.0; n * n] };
        for i in 0..n {
            m[(i, i)] = 1.0;
        }
        m
    }

    fn transpose(&self) -> Matrix {
        let mut t = Matrix { rows: self.cols, cols: self.rows, data: vec![0.0; self.data.len()] };
        for r in 0..self.rows {
            for c in 0..self.cols {
                t[(c, r)] = self[(r, c)];
            }
        }
        t
    }
}

unitTests:
fn m(v: Vec<Vec<f64>>) -> Matrix { Matrix::try_from(v).unwrap() }

test("building from rows", || {
    let a = m(vec![vec![1.0, 2.0, 3.0], vec![4.0, 5.0, 6.0]]);
    check_eq((a.rows, a.cols), (2, 3));
    check_eq(a[(1, 2)], 6.0);
    check(Matrix::try_from(Vec::<Vec<f64>>::new()).is_err());
    check(Matrix::try_from(vec![vec![]]).is_err());
    check(Matrix::try_from(vec![vec![1.0], vec![1.0, 2.0]]).is_err());
});

test("index mut", || {
    let mut a = Matrix::identity(2);
    a[(0, 1)] = 7.0;
    check_eq(a.data, vec![1.0, 7.0, 0.0, 1.0]);
});

test("product and transpose", || {
    let a = m(vec![vec![1.0, 2.0], vec![3.0, 4.0]]);
    let b = m(vec![vec![5.0, 6.0], vec![7.0, 8.0]]);
    check_eq(&a * &b, m(vec![vec![19.0, 22.0], vec![43.0, 50.0]]));
    check_eq(&a * &Matrix::identity(2), a.clone());
    let c = m(vec![vec![1.0, 2.0, 3.0]]);
    check_eq(c.transpose(), m(vec![vec![1.0], vec![2.0], vec![3.0]]));
    check_eq((&c * &c.transpose())[(0, 0)], 14.0);
});

test("wrong sizes panic", || {
    check_panics(|| { let _ = &m(vec![vec![1.0, 2.0]]) * &m(vec![vec![1.0, 2.0]]); });
    check_panics(|| { let _ = Matrix::identity(2)[(2, 0)]; });
});

